using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

// MCP SDK discovers this class via [McpServerToolType].
// The runtime creates ONE instance per tool invocation,
// injecting constructor parameters from the DI container.
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // IHttpClientFactory is resolved from DI (registered in Program.cs).
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _http = httpClientFactory.CreateClient("WeatherApi");
    }

    [McpServerTool(Name = "get_forecast"),
     Description("Get a weather forecast for a location.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")]  double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        var doc = await _http.GetFromJsonAsync<JsonDocument>(url);
        if (doc is null) return "No data returned from API.";

        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool(Name = "get_current_temperature"),
     Description("Get only the current temperature for a location.")]
    public async Task<string> GetCurrentTemperature(
        [Description("Latitude")]  double latitude,
        [Description("Longitude")] double longitude)
    {
        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m";

        var doc = await _http.GetFromJsonAsync<JsonDocument>(url);
        if (doc is null) return "No data returned from API.";

        var temp = doc.RootElement
            .GetProperty("current")
            .GetProperty("temperature_2m")
            .GetDouble();

        var units = doc.RootElement
            .GetProperty("current_units")
            .GetProperty("temperature_2m")
            .GetString();

        return $"{temp} {units}";
    }
}

// System.ComponentModel provides [Description] — it's what the MCP SDK reads
// to populate tool/parameter descriptions sent to the LLM.

